              hints: ['tcpdump -nni eth3 \'tcp[tcpflags] & (…) != 0\'', '<code>tcpdump -nni eth3 \'tcp[tcpflags] &amp; (tcp-syn|tcp-rst) != 0\'</code>'], steps: EX(['tcpdump -nni eth3 \'tcp[tcpflags] & (tcp-syn|tcp-rst) != 0\'']),
