        id: 'cp-20', vendor: 'checkpoint', level: 1, title: 'Komşu görünmüyor: ARP ve Proxy ARP', minutes: 20, kind: 'firewall', hostname: 'gw-a', pre: ['cp-17'], ordered: true,
