        goals: ['ip neigh durumlarını okumak (REACHABLE / STALE / FAILED)', 'tcpdump ile ARP isteği ve yanıtı', 'fw ctl arp ile Proxy ARP kayıtları', 'Manuel NAT ve local.arp ilişkisi'],
